/**
 * Process Mining SDK
 *
 * A TypeScript SDK for the Process Mining Platform API.
 * Uses business verbs following CodeOpinion guidance.
 *
 * @example
 * ```typescript
 * import { ProcessMiningSdk } from 'process-mining-sdk';
 *
 * const sdk = new ProcessMiningSdk({ baseUrl: 'http://localhost:8001' });
 *
 * // Sign in
 * await sdk.auth.signIn({ email: 'user@example.com', password: 'test' });
 *
 * // Ingest event log
 * const log = await sdk.logs.ingest(file, { name: 'My Process' });
 *
 * // Discover process model
 * const model = await sdk.discovery.discover({ logId: log.id, minerType: 'inductive' });
 *
 * // Check conformance
 * const result = await sdk.conformance.check({ logId: log.id, modelId: model.modelId });
 *
 * // Find bottlenecks
 * const bottlenecks = await sdk.performance.findBottlenecks(log.id);
 * ```
 */

import { HttpClient } from "./client.js";
import { SdkConfig } from "./types/common.js";

// Import all clients
import { AuthClient } from "./clients/auth.client.js";
import { LogsClient } from "./clients/logs.client.js";
import { DiscoveryClient } from "./clients/discovery.client.js";
import { ConformanceClient } from "./clients/conformance.client.js";
import { PerformanceClient } from "./clients/performance.client.js";
import { AnalyticsClient } from "./clients/analytics.client.js";
import { OCPMClient } from "./clients/ocpm.client.js";
import { OrgClient } from "./clients/org.client.js";
import { ModelsClient } from "./clients/models.client.js";
import { WorkflowsClient } from "./clients/workflows.client.js";
import { NotificationsClient } from "./clients/notifications.client.js";
import { IntegrationsClient } from "./clients/integrations.client.js";
import { ProcessMiningClient } from "./clients/process-mining.client.js";

/**
 * Process Mining SDK
 *
 * Main entry point for all API operations.
 * Provides domain-specific clients with business-focused method names.
 */
export class ProcessMiningSdk {
  private readonly http: HttpClient;

  /** Authentication operations (signIn, signOut, whoAmI) */
  public readonly auth: AuthClient;

  /** Event log operations (ingest, analyze, assessQuality) */
  public readonly logs: LogsClient;

  /** Process discovery operations (discover, buildDFG, extractPetriNet) */
  public readonly discovery: DiscoveryClient;

  /** Conformance checking operations (check, measureFitness, computeAlignments) */
  public readonly conformance: ConformanceClient;

  /** Performance analysis operations (analyze, findBottlenecks, summarize) */
  public readonly performance: PerformanceClient;

  /** Analytics operations (getDashboard, discoverInsights, detectAnomalies) */
  public readonly analytics: AnalyticsClient;

  /** Object-Centric Process Mining operations (ingest, discoverOCPN) */
  public readonly ocpm: OCPMClient;

  /** Organizational mining operations (profileResources, buildHandoverNetwork, discoverRoles) */
  public readonly org: OrgClient;

  /** Process model management operations (list, get, visualize) */
  public readonly models: ModelsClient;

  /** Workflow automation operations (start, listPipelines, cancel) */
  public readonly workflows: WorkflowsClient;

  /** Notification operations (send, subscribe, configure) */
  public readonly notifications: NotificationsClient;

  /** External integration operations (createConnector, sync, fetchData) */
  public readonly integrations: IntegrationsClient;

  /** PM4Py advanced features (analyzeFootprints, extractLogSkeleton, analyzeSNA) */
  public readonly processMining: ProcessMiningClient;

  constructor(config: SdkConfig) {
    this.http = new HttpClient(config);

    // Initialize all clients
    this.auth = new AuthClient(this.http);
    this.logs = new LogsClient(this.http);
    this.discovery = new DiscoveryClient(this.http);
    this.conformance = new ConformanceClient(this.http);
    this.performance = new PerformanceClient(this.http);
    this.analytics = new AnalyticsClient(this.http);
    this.ocpm = new OCPMClient(this.http);
    this.org = new OrgClient(this.http);
    this.models = new ModelsClient(this.http);
    this.workflows = new WorkflowsClient(this.http);
    this.notifications = new NotificationsClient(this.http);
    this.integrations = new IntegrationsClient(this.http);
    this.processMining = new ProcessMiningClient(this.http);
  }

  /**
   * Check if user is authenticated.
   */
  isAuthenticated(): boolean {
    return this.http.isAuthenticated();
  }
}

// Export the SDK class and config type
export type { SdkConfig };

// Re-export all types
export * from "./types/index.js";

// Re-export individual clients for advanced usage
export { AuthClient } from "./clients/auth.client.js";
export { LogsClient } from "./clients/logs.client.js";
export { DiscoveryClient } from "./clients/discovery.client.js";
export { ConformanceClient } from "./clients/conformance.client.js";
export { PerformanceClient } from "./clients/performance.client.js";
export { AnalyticsClient } from "./clients/analytics.client.js";
export { OCPMClient } from "./clients/ocpm.client.js";
export { OrgClient } from "./clients/org.client.js";
export { ModelsClient } from "./clients/models.client.js";
export { WorkflowsClient } from "./clients/workflows.client.js";
export { NotificationsClient } from "./clients/notifications.client.js";
export { IntegrationsClient } from "./clients/integrations.client.js";
export { ProcessMiningClient } from "./clients/process-mining.client.js";

/**
 * Base HTTP Client for Process Mining SDK
 * Handles authentication, error normalization, and request/response processing
 */

import { ApiError, ProblemDetails, SdkConfig, AuthState } from "./types/common.js";

export class HttpClient {
  private baseUrl: string;
  private apiPrefix: string;
  private timeout: number;
  private authState: AuthState = {
    accessToken: null,
    tokenType: "bearer",
    isAuthenticated: false,
  };
  private onAuthError?: () => void;

  constructor(config: SdkConfig) {
    this.baseUrl = config.baseUrl.replace(/\/$/, "");
    this.apiPrefix = config.apiPrefix ?? "/api/v1";
    this.timeout = config.timeout ?? 30000;
    this.onAuthError = config.onAuthError;
  }

  /**
   * Set authentication token after successful login
   */
  setAuth(token: string, tokenType = "bearer"): void {
    this.authState = {
      accessToken: token,
      tokenType,
      isAuthenticated: true,
    };
  }

  /**
   * Clear authentication state
   */
  clearAuth(): void {
    this.authState = {
      accessToken: null,
      tokenType: "bearer",
      isAuthenticated: false,
    };
  }

  /**
   * Check if client is authenticated
   */
  isAuthenticated(): boolean {
    return this.authState.isAuthenticated;
  }

  /**
   * Build full URL for API endpoint
   */
  private buildUrl(path: string): string {
    const normalizedPath = path.startsWith("/") ? path : `/${path}`;
    return `${this.baseUrl}${this.apiPrefix}${normalizedPath}`;
  }

  /**
   * Build request headers
   */
  private buildHeaders(contentType?: string): HeadersInit {
    const headers: Record<string, string> = {};

    if (this.authState.accessToken) {
      headers["Authorization"] = `${this.authState.tokenType} ${this.authState.accessToken}`;
    }

    if (contentType) {
      headers["Content-Type"] = contentType;
    }

    return headers;
  }

  /**
   * Process response and handle errors
   */
  private async processResponse<T>(response: Response): Promise<T> {
    if (!response.ok) {
      // Handle 401 Unauthorized
      if (response.status === 401) {
        this.clearAuth();
        this.onAuthError?.();
      }

      // Try to parse RFC 7807 Problem Details
      let problem: ProblemDetails;
      try {
        problem = (await response.json()) as ProblemDetails;
      } catch {
        problem = {
          type: "about:blank",
          title: response.statusText || "Request Failed",
          status: response.status,
        };
      }

      throw new ApiError(response.status, problem);
    }

    // Handle 204 No Content
    if (response.status === 204) {
      return undefined as T;
    }

    // Check content type
    const contentType = response.headers.get("content-type");
    if (contentType?.includes("application/json")) {
      return response.json() as Promise<T>;
    }

    // Return text for other content types (e.g., SVG)
    return response.text() as Promise<T>;
  }

  /**
   * Make GET request
   */
  async get<T>(
    path: string,
    params?: Record<string, string | number | boolean | undefined>
  ): Promise<T> {
    const url = new URL(this.buildUrl(path));

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined) {
          url.searchParams.append(key, String(value));
        }
      });
    }

    const response = await fetch(url.toString(), {
      method: "GET",
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeout),
    });

    return this.processResponse<T>(response);
  }

  /**
   * Make POST request with JSON body
   */
  async post<T>(path: string, body?: unknown): Promise<T> {
    const response = await fetch(this.buildUrl(path), {
      method: "POST",
      headers: this.buildHeaders("application/json"),
      body: body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(this.timeout),
    });

    return this.processResponse<T>(response);
  }

  /**
   * Make POST request with FormData (for file uploads)
   */
  async postForm<T>(path: string, formData: FormData): Promise<T> {
    const response = await fetch(this.buildUrl(path), {
      method: "POST",
      headers: this.buildHeaders(), // No Content-Type - browser sets it with boundary
      body: formData,
      signal: AbortSignal.timeout(this.timeout),
    });

    return this.processResponse<T>(response);
  }

  /**
   * Make PATCH request
   */
  async patch<T>(path: string, body: unknown): Promise<T> {
    const response = await fetch(this.buildUrl(path), {
      method: "PATCH",
      headers: this.buildHeaders("application/json"),
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(this.timeout),
    });

    return this.processResponse<T>(response);
  }

  /**
   * Make DELETE request
   */
  async delete<T>(path: string): Promise<T> {
    const response = await fetch(this.buildUrl(path), {
      method: "DELETE",
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeout),
    });

    return this.processResponse<T>(response);
  }
}

/**
 * Auth Client - Authentication Operations
 *
 * Business verbs:
 * - signIn() - Authenticate user and start session
 * - signOut() - End session
 * - whoAmI() - Get current user profile
 */

import { HttpClient } from "../client.js";
import { AuthToken, LoginCredentials, UserProfile } from "../types/auth.js";

export class AuthClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * Sign in with email and password.
   * Returns access token for authenticated requests.
   */
  async signIn(credentials: LoginCredentials): Promise<AuthToken> {
    const response = await this.http.post<{
      access_token: string;
      token_type: string;
    }>("/auth/login", credentials);

    // Store token in client
    this.http.setAuth(response.access_token, response.token_type);

    return {
      accessToken: response.access_token,
      tokenType: response.token_type,
    };
  }

  /**
   * Sign out and clear session.
   */
  async signOut(): Promise<void> {
    await this.http.post("/auth/logout");
    this.http.clearAuth();
  }

  /**
   * Get the current authenticated user's profile.
   */
  async whoAmI(): Promise<UserProfile> {
    return this.http.get<UserProfile>("/auth/me");
  }

  /**
   * Check if user is currently authenticated.
   */
  isAuthenticated(): boolean {
    return this.http.isAuthenticated();
  }
}

/**
 * Conformance Client - Conformance Checking Operations
 *
 * Business verbs:
 * - check() - Check conformance between log and model
 * - measureFitness() - Calculate fitness score
 * - measurePrecision() - Calculate precision score
 * - diagnose() - Get detailed conformance diagnostics
 * - findDeviations() - Detect deviations from model
 * - computeAlignments() - Calculate optimal alignments
 * - analyzeDeviationPatterns() - Cluster and analyze deviation patterns
 * - evaluateComprehensiveQuality() - Get all quality metrics
 */

import { HttpClient } from "../client.js";
import {
  CheckConformanceOptions,
  ConformanceResult,
  ConformanceDiagnostics,
  Deviation,
  DeviationAnalysis,
  AlignmentAnalysis,
  ComprehensiveQuality,
} from "../types/conformance.js";

export class ConformanceClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * Check conformance between an event log and a process model.
   * Returns overall fitness and conformance status.
   */
  async check(options: CheckConformanceOptions): Promise<ConformanceResult> {
    const response = await this.http.post<{
      result_id: string;
      log_id: string;
      model_id: string;
      fitness: number;
      precision?: number;
      is_conformant: boolean;
      method: string;
    }>("/conformance/check", {
      log_id: options.logId,
      model_id: options.modelId,
      method: options.method ?? "token_replay",
    });

    return {
      resultId: response.result_id,
      logId: response.log_id,
      modelId: response.model_id,
      fitness: response.fitness,
      precision: response.precision,
      isConformant: response.is_conformant,
      method: response.method,
    };
  }

  /**
   * Measure fitness score between log and model.
   * Fitness measures how well the log fits the model.
   */
  async measureFitness(logId: string, modelId: string): Promise<number> {
    const response = await this.http.get<{ fitness: number }>("/conformance/fitness", {
      log_id: logId,
      model_id: modelId,
    });
    return response.fitness;
  }

  /**
   * Measure precision score between log and model.
   * Precision measures how much behavior the model allows beyond the log.
   */
  async measurePrecision(logId: string, modelId: string): Promise<number> {
    const response = await this.http.get<{ precision: number }>("/conformance/precision", {
      log_id: logId,
      model_id: modelId,
    });
    return response.precision;
  }

  /**
   * Get detailed conformance diagnostics.
   * Shows fitting vs non-fitting traces and deviations.
   */
  async diagnose(logId: string, modelId: string): Promise<ConformanceDiagnostics> {
    return this.http.get<ConformanceDiagnostics>("/conformance/diagnostics", {
      log_id: logId,
      model_id: modelId,
    });
  }

  /**
   * Find deviations from the process model.
   * Returns cases that don't conform and their deviation details.
   */
  async findDeviations(logId: string, modelId: string, threshold = 0.8): Promise<Deviation[]> {
    const response = await this.http.get<{ deviations: Deviation[] }>("/conformance/deviations", {
      log_id: logId,
      model_id: modelId,
      threshold,
    });
    return response.deviations;
  }

  /**
   * Compute optimal alignments between log traces and model.
   * Shows sync moves, model moves, and log moves for each trace.
   */
  async computeAlignments(logId: string, modelId: string, limit = 100): Promise<AlignmentAnalysis> {
    return this.http.get<AlignmentAnalysis>("/conformance/alignments", {
      log_id: logId,
      model_id: modelId,
      limit,
    });
  }

  /**
   * Analyze and cluster deviation patterns.
   * Groups similar deviations and provides occurrence statistics.
   */
  async analyzeDeviationPatterns(logId: string, modelId: string): Promise<DeviationAnalysis> {
    return this.http.get<DeviationAnalysis>("/conformance/deviation-patterns", {
      log_id: logId,
      model_id: modelId,
    });
  }

  /**
   * Evaluate comprehensive quality metrics.
   * Combines fitness, precision, generalization, and simplicity.
   */
  async evaluateComprehensiveQuality(
    logId: string,
    modelId: string
  ): Promise<ComprehensiveQuality> {
    return this.http.get<ComprehensiveQuality>("/conformance/comprehensive-quality", {
      log_id: logId,
      model_id: modelId,
    });
  }
}

/**
 * Discovery Client - Process Model Discovery Operations
 *
 * Business verbs:
 * - discover() - Discover process model from event log
 * - buildDFG() - Build Directly-Follows Graph
 * - extractPetriNet() - Extract Petri Net from model
 * - extractProcessTree() - Extract Process Tree from model
 * - visualize() - Generate visual representation
 * - evaluateQuality() - Evaluate model quality metrics
 * - listMiners() - Get available mining algorithms
 */

import { HttpClient } from "../client.js";
import {
  DiscoverModelOptions,
  ProcessModel,
  DirectlyFollowsGraph,
  PetriNet,
  ProcessTree,
  ModelQualityMetrics,
  MinerInfo,
} from "../types/discovery.js";

export class DiscoveryClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * List all available mining algorithms.
   */
  async listMiners(): Promise<MinerInfo[]> {
    return this.http.get<MinerInfo[]>("/discovery/miners");
  }

  /**
   * Discover a process model from an event log.
   * Uses the specified mining algorithm (default: inductive miner).
   */
  async discover(options: DiscoverModelOptions): Promise<ProcessModel> {
    const response = await this.http.post<{
      model_id: string;
      model_name: string;
      miner_type: string;
      model_format: string;
      source_log_id: string;
    }>("/discovery/discover", {
      log_id: options.logId,
      miner_type: options.minerType ?? "inductive",
      model_name: options.modelName,
    });

    return {
      modelId: response.model_id,
      modelName: response.model_name,
      minerType: response.miner_type,
      modelFormat: response.model_format,
      sourceLogId: response.source_log_id,
    };
  }

  /**
   * Build a Directly-Follows Graph from an event log.
   * Returns nodes (activities) and edges (transitions) with frequencies.
   */
  async buildDFG(logId: string): Promise<DirectlyFollowsGraph> {
    return this.http.get<DirectlyFollowsGraph>(`/discovery/dfg/${logId}/detailed`);
  }

  /**
   * Build a simple DFG representation (JSON).
   */
  async buildSimpleDFG(
    logId: string
  ): Promise<{
    nodes: string[];
    edges: Array<{ source: string; target: string; frequency: number }>;
  }> {
    return this.http.get(`/discovery/dfg/${logId}`);
  }

  /**
   * Extract Petri Net representation from a process model.
   * Returns places, transitions, arcs, and markings.
   */
  async extractPetriNet(modelId: string): Promise<PetriNet> {
    return this.http.get<PetriNet>(`/discovery/petri-net/${modelId}`);
  }

  /**
   * Extract Process Tree representation from a process model.
   * Returns hierarchical tree structure.
   */
  async extractProcessTree(modelId: string): Promise<ProcessTree> {
    return this.http.get<ProcessTree>(`/discovery/process-tree/${modelId}`);
  }

  /**
   * Generate visual representation of a process model.
   * Returns SVG image by default.
   */
  async visualize(modelId: string, format: "svg" | "png" = "svg"): Promise<string> {
    return this.http.get<string>(`/discovery/visualize/${modelId}`, { format });
  }

  /**
   * Evaluate quality metrics of a process model.
   * Returns fitness, precision, generalization, and simplicity scores.
   */
  async evaluateQuality(modelId: string, logId?: string): Promise<ModelQualityMetrics> {
    const params: Record<string, string | undefined> = {};
    if (logId) params.log_id = logId;
    return this.http.get<ModelQualityMetrics>(`/discovery/model/${modelId}/quality`, params);
  }
}

/**
 * Integrations Client - External System Connectors
 *
 * Business verbs:
 * - listConnectorTypes() - Get available connector types
 * - createConnector() - Create new connector
 * - listConnectors() - List all connectors
 * - getConnector() - Get connector details
 * - removeConnector() - Delete connector
 * - connect() - Connect to external system
 * - disconnect() - Disconnect from external system
 * - testConnection() - Test connector connection
 * - sync() - Synchronize data from external system
 * - listTables() - Get available tables from connector
 * - fetchData() - Fetch event data from connector
 */

import { HttpClient } from "../client.js";
import {
  ConnectorTypeInfo,
  Connector,
  CreateConnectorOptions,
  SyncResult,
} from "../types/workflows.js";

export class IntegrationsClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * List available connector types.
   */
  async listConnectorTypes(): Promise<ConnectorTypeInfo[]> {
    return this.http.get<ConnectorTypeInfo[]>("/integrations/connector-types");
  }

  /**
   * Create a new connector configuration.
   */
  async createConnector(options: CreateConnectorOptions): Promise<Connector> {
    return this.http.post<Connector>("/integrations/connectors", {
      name: options.name,
      connector_type: options.connectorType,
      settings: options.settings,
    });
  }

  /**
   * List all configured connectors.
   */
  async listConnectors(): Promise<Connector[]> {
    return this.http.get<Connector[]>("/integrations/connectors");
  }

  /**
   * Get connector details.
   */
  async getConnector(connectorId: string): Promise<Connector> {
    return this.http.get<Connector>(`/integrations/connectors/${connectorId}`);
  }

  /**
   * Remove a connector configuration.
   */
  async removeConnector(connectorId: string): Promise<void> {
    await this.http.delete(`/integrations/connectors/${connectorId}`);
  }

  /**
   * Connect to an external system.
   */
  async connect(connectorId: string): Promise<{ status: string }> {
    return this.http.post(`/integrations/connectors/${connectorId}/connect`);
  }

  /**
   * Disconnect from an external system.
   */
  async disconnect(connectorId: string): Promise<{ status: string }> {
    return this.http.post(`/integrations/connectors/${connectorId}/disconnect`);
  }

  /**
   * Test connector connection.
   */
  async testConnection(connectorId: string): Promise<{ success: boolean; message: string }> {
    return this.http.post(`/integrations/connectors/${connectorId}/test`);
  }

  /**
   * Synchronize data from external system.
   */
  async sync(connectorId: string): Promise<SyncResult> {
    return this.http.post<SyncResult>(`/integrations/connectors/${connectorId}/sync`);
  }

  /**
   * List available tables from a connected data source.
   */
  async listTables(connectorId: string): Promise<string[]> {
    const response = await this.http.get<{ tables: string[] }>(
      `/integrations/connectors/${connectorId}/tables`
    );
    return response.tables;
  }

  /**
   * Fetch event data from connector into the system.
   */
  async fetchData(
    connectorId: string,
    tableName: string,
    columnMapping: Record<string, string>
  ): Promise<{ logId: string; eventsImported: number }> {
    return this.http.post(`/integrations/connectors/${connectorId}/fetch`, {
      table_name: tableName,
      column_mapping: columnMapping,
    });
  }

  /**
   * Get synchronization history.
   */
  async getSyncHistory(): Promise<SyncResult[]> {
    return this.http.get<SyncResult[]>("/integrations/sync-history");
  }
}

/**
 * Analytics Client - Process Analytics Operations
 *
 * Business verbs:
 * - getDashboard() - Get comprehensive dashboard data
 * - discoverInsights() - Find process insights
 * - detectAnomalies() - Identify anomalous cases
 * - analyzeVariants() - Analyze variant distribution
 * - analyzeResources() - Analyze resource utilization
 * - analyzeTime() - Analyze temporal patterns
 */

import { HttpClient } from "../client.js";
import {
  DashboardData,
  ProcessInsight,
  AnomalyAnalysis,
  VariantStatistics,
  ResourceStatistics,
  TimeAnalysis,
} from "../types/analytics.js";

export class AnalyticsClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * Get comprehensive dashboard data for an event log.
   * Includes overview metrics, top variants, and distributions.
   */
  async getDashboard(logId: string): Promise<DashboardData> {
    return this.http.get<DashboardData>(`/analytics/dashboard/${logId}`);
  }

  /**
   * Discover process insights from the event log.
   * Returns actionable findings with recommendations.
   */
  async discoverInsights(logId: string): Promise<ProcessInsight[]> {
    const response = await this.http.get<{ insights: ProcessInsight[] }>(
      `/analytics/insights/${logId}`
    );
    return response.insights;
  }

  /**
   * Detect anomalous cases in the event log.
   * Identifies cases that deviate from normal behavior.
   */
  async detectAnomalies(logId: string): Promise<AnomalyAnalysis> {
    return this.http.get<AnomalyAnalysis>(`/analytics/anomalies/${logId}`);
  }

  /**
   * Analyze variant distribution and statistics.
   */
  async analyzeVariants(logId: string): Promise<VariantStatistics> {
    return this.http.get<VariantStatistics>(`/analytics/variants/${logId}`);
  }

  /**
   * Analyze resource utilization and workload.
   */
  async analyzeResources(logId: string): Promise<ResourceStatistics> {
    return this.http.get<ResourceStatistics>(`/analytics/resources/${logId}`);
  }

  /**
   * Analyze temporal patterns in the process.
   * Returns cases over time, peak hours, and duration trends.
   */
  async analyzeTime(logId: string): Promise<TimeAnalysis> {
    return this.http.get<TimeAnalysis>(`/analytics/time/${logId}`);
  }
}

/**
 * Logs Client - Event Log Operations
 *
 * Business verbs (following CodeOpinion guidance):
 * - ingest() - Import event log file into system
 * - preview() - Preview file before ingestion
 * - detectColumns() - Auto-detect CSV column mappings
 * - analyze() - Get log statistics
 * - assessQuality() - Run quality assessment
 * - listVariants() - Get process variants
 * - listActivities() - Get all activities
 * - remove() - Delete event log
 */

import { HttpClient } from "../client.js";
import { PaginationOptions } from "../types/common.js";
import {
  EventLog,
  EventLogDetails,
  IngestLogOptions,
  IngestionResult,
  ColumnDetection,
  FilePreview,
  LogStatistics,
  QualityReport,
  ProcessVariant,
  PaginatedLogs,
  UpdateLogMetadata,
} from "../types/logs.js";

export interface ListLogsOptions extends PaginationOptions {
  search?: string;
  sortBy?: "created_at" | "name" | "total_cases" | "total_events";
  sortOrder?: "asc" | "desc";
}

export class LogsClient {
  constructor(private readonly http: HttpClient) {}

  /**
   * Ingest an event log file into the system.
   * Supports CSV and XES formats.
   */
  async ingest(file: File | Blob, options?: IngestLogOptions): Promise<IngestionResult> {
    const formData = new FormData();
    formData.append("file", file);

    if (options?.name) formData.append("name", options.name);
    if (options?.caseIdColumn) formData.append("case_id_column", options.caseIdColumn);
    if (options?.activityColumn) formData.append("activity_column", options.activityColumn);
    if (options?.timestampColumn) formData.append("timestamp_column", options.timestampColumn);
    if (options?.resourceColumn) formData.append("resource_column", options.resourceColumn);

    const response = await this.http.postForm<{
      id: string;
      name: string;
      total_cases: number;
      total_events: number;
      validation: { is_valid: boolean; errors: string[]; warnings: string[] };
    }>("/logs/upload", formData);

    return {
      id: response.id,
      name: response.name,
      totalCases: response.total_cases,
      totalEvents: response.total_events,
      validation: {
        isValid: response.validation.is_valid,
        errors: response.validation.errors,
        warnings: response.validation.warnings,
      },
    };
  }

  /**
   * Preview a file before ingestion.
   * Returns column information and sample rows.
   */
  async preview(file: File | Blob): Promise<FilePreview> {
    const formData = new FormData();
    formData.append("file", file);
    return this.http.postForm<FilePreview>("/logs/preview", formData);
  }

  /**
   * Detect column types from a CSV file.
   * Suggests mappings for case ID, activity, timestamp, and resource.
   */
  async detectColumns(file: File | Blob): Promise<ColumnDetection> {
    const formData = new FormData();
    formData.append("file", file);
    return this.http.postForm<ColumnDetection>("/logs/detect-columns", formData);
  }

  /**
   * List all event logs with optional filtering and pagination.
   */
  async list(options?: ListLogsOptions): Promise<PaginatedLogs> {
    return this.http.get<PaginatedLogs>("/logs/", {
      page: options?.page,
      page_size: options?.pageSize,
      search: options?.search,
      sort_by: options?.sortBy,
      sort_order: options?.sortOrder,
    });
  }

  /**
   * Get detailed information about a specific event log.
   */
  async get(logId: string): Promise<EventLogDetails> {
    return this.http.get<EventLogDetails>(`/logs/${logId}`);
  }

  /**
   * Update event log metadata.
   */
  async updateMetadata(logId: string, updates: UpdateLogMetadata): Promise<EventLog> {
    return this.http.patch<EventLog>(`/logs/${logId}`, updates);
  }

  /**
   * Analyze event log and get detailed statistics.
   */
  async analyze(logId: string): Promise<LogStatistics> {
    return this.http.get<LogStatistics>(`/logs/${logId}/statistics`);
  }

  /**
   * Assess quality of an event log.
   * Returns completeness, validity scores, and issues found.
   */
  async assessQuality(logId: string): Promise<QualityReport> {
    return this.http.get<QualityReport>(`/logs/${logId}/quality`);
  }

  /**
   * List process variants in an event log.
   */
  async listVariants(logId: string, limit = 50): Promise<ProcessVariant[]> {
    return this.http.get<ProcessVariant[]>(`/logs/${logId}/variants`, { limit });
  }

  /**
   * List all unique activities in an event log.
   */
  async listActivities(logId: string): Promise<string[]> {
    const response = await this.http.get<{ activities: string[] }>(`/logs/${logId}/activities`);
    return response.activities;
  }

  /**
   * Remove an event log from the system.
   */
  async remove(logId: string): Promise<void> {
    await this.http.delete(`/logs/${logId}`);
  }
}

